import os
R=os.path.dirname(os.path.abspath(__file__))+'/'
S=R+'src/'
os.makedirs(R+'build',exist_ok=True)
old=open(S+'content-base.html').read().split('\n')
L=lambda a,b:'\n'.join(old[a-1:b])
content='\n'.join([
 '/* ===== content carried over from ESQ Ready 1.x (procedures, lessons, illustrations) ===== */',
 L(764,799), L(802,849), L(850,1118), L(1119,1119), L(1135,1188), L(1191,1204), L(1226,1227), L(1229,1522), L(1677,1704), L(2170,2185)])
content=content.replace('ESQ Ready challenge','Everyday Safe challenge').replace("'img/intro-mobility.webp','A helper pushes a person in a wheelchair past a stairwell door toward the elevator lobby, marked with a blue wheelchair sign.'","'img/intro-mobility.webp','A colleague pushes a teammate in a wheelchair past the stairwell door toward the elevator lobby, marked with a wheelchair sign.'").replace("plan:['img/12e9a95705.webp','A person studies an emergency floor plan on the wall, with symbols for an exit, an accessible area and an AED.']","plan:['img/plan2.webp','Colleagues point out the safety symbols on their floor: the emergency stairwell, the mobility rescue area and the AED cabinet.']").replace("plan:['img/fb1729aa60.webp','Next to a new desk, a person studies the emergency floor plan posted on the wall, with exit, AED, mobility rescue and muster symbols.']","plan:['img/plan2.webp','Colleagues point out the safety symbols on their floor: the emergency stairwell, the mobility rescue area and the AED cabinet.']").replace("missing:['img/9cc4ed1728.webp','Three people at a muster point sign. One looks back, worried, toward a washroom door.']","missing:['img/missing2.webp','Outside, a worried colleague realizes someone may still be in the washroom inside.']").replace("escalator:['img/9ca5c52d5d.webp','Two people riding an escalator up toward an exit door.']","escalator:['img/escalator3.webp','Two colleagues stand near the escalators. One points toward them as a way out.']").replace("quiet:['img/891f1609b3.webp','Two people hesitate near a stairwell door under a silent alarm while a third points back toward the door.']","quiet:['img/allclear.webp','Two colleagues in winter coats wait outside the stairwell door until the speaker announces the All Clear.']").replace("outside:['img/100208ac85.webp','A person walks away from an exit door toward a muster point sign.']","outside:['img/outside2.webp','A colleague in a winter coat walks across the plaza toward a green muster point sign.']").replace("levels:['img/a4711bd6dd.webp','At the bottom of the stairs, a person walks out through an exit door to the outside, instead of continuing toward the LRT platform.']","levels:['img/levels2.webp','At the bottom of the stairs, a colleague in a winter coat pushes through the main floor exit doors, away from the LRT platform.']").replace("pushbar:['img/af49350a37.webp','A person pushes the bar on a stairwell door while it beeps.']","pushbar:['img/push2.webp','A colleague in a winter coat holds the push bar on a stairwell door while it beeps.']").replace("evac:['img/f75b666344.webp','A person walks away from their desk under a ceiling alarm, past an open stairwell door with an exit sign, away from the elevator.']","evac:['img/stair4.webp','A colleague in a winter coat stands at a stairwell door marked with a red EXIT sign and a Stairwell sign.']").replace("alarm:['img/7f1a9c2a2c.webp','A person on the phone at their desk while an alarm bell rings.']","alarm:['img/alarm3.webp','A colleague on a phone call at their desk looks up, worried, as the alarm bell rings.']").replace("evac:['img/4851e46496.webp','A person leaves their desk, walks through an exit door and outside to a muster point sign.']","evac:['img/intro-evac2.webp','From desk to muster point: a colleague leaves her desk, goes through the stairwell door with its push bar, and meets others at the green muster point sign.']")
js='(function(){\n"use strict";\n'+open(S+'app1.js').read()+'\n'+content+'\n'+''.join(open(S+f'app{i}.js').read()+'\n' for i in (2,3,'3b','3c',4,5))+'})();'
open(R+'index.html','w').write('<!DOCTYPE html>\n<html lang="en-CA">\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width,initial-scale=1">\n'+open(S+'head.html').read()+open(S+'body.html').read()+'\n<script>\n'+js+'\n</script>\n')
open(R+'build/app.js','w').write(js)
print(len(js))

# test build with hooks for the automated tests
s=open(R+'index.html').read()
open(R+'tests/test.html','w').write(s.replace('let PL=null;','let PL=null; window.__PL=()=>PL; window.__S=()=>S; window.__QB=()=>QB; window.HZ_IDS=()=>HZ.filter(h=>h.haz).map(h=>h.id); window.__PLANS=()=>PLANS;',1))
# standalone: bank inlined so it opens by double-click
bank=open(R+'data/bank.json').read()
old="bankP=fetch('data/bank.json',{cache:'no-cache'}).then(r=>{if(!r.ok) throw new Error('bank '+r.status); return r.json();})"
sa=s.replace(old,"bankP=(window.__BANK?Promise.resolve(window.__BANK):fetch('data/bank.json',{cache:'no-cache'}).then(r=>{if(!r.ok) throw new Error('bank '+r.status); return r.json();}))")
open(R+'standalone.html','w').write('<!doctype html>\n<html lang="en-CA">\n<head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width,initial-scale=1">\n<script>window.__BANK='+bank.replace('</','<\\/')+';</script>\n'+sa+'\n</body>\n</html>\n')
